import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { 
    Box, Typography, Paper, Table, TableBody, TableCell, 
    TableContainer, TableHead, TableRow, CircularProgress, 
    Snackbar, Alert
} from '@mui/material';
import axios from 'axios';

const ViewStdAttendance = () => {
    const { currentUser } = useSelector(state => state.user);
    const [attendanceData, setAttendanceData] = useState([]);
    const [loading, setLoading] = useState(true);
    const [openSnackbar, setOpenSnackbar] = useState(false);

    useEffect(() => {
        const fetchAttendance = async () => {
            try {
                const token = localStorage.getItem('token') || localStorage.getItem('authToken');
                const studentId = currentUser._id || currentUser.id;
                const res = await axios.get(`${process.env.REACT_APP_BASE_URL || 'http://localhost:5000'}/api/attendance/student/${studentId}`, {
                    headers: { Authorization: `Bearer ${token}` }
                });

                // Group by course
                const grouped = {};
                res.data.forEach(record => {
                    const courseId = record.course._id || record.course;
                    const courseName = record.course.subName || record.course.name || record.course.courseName || `Course ${courseId}`;
                    
                    if (!grouped[courseId]) {
                        grouped[courseId] = { courseName, present: 0, absent: 0, total: 0 };
                    }
                    
                    grouped[courseId].total += 1;
                    if (record.status === 'Present') {
                        grouped[courseId].present += 1;
                    } else {
                        grouped[courseId].absent += 1;
                    }
                });

                const dataArray = Object.values(grouped).map(item => ({
                    ...item,
                    percentage: item.total > 0 ? Math.round((item.present / item.total) * 100) : 0
                }));

                setAttendanceData(dataArray);
                
                if (dataArray.length === 0) {
                    setOpenSnackbar(true);
                }
            } catch (error) {
                console.error("Failed to fetch attendance", error);
            } finally {
                setLoading(false);
            }
        };

        if (currentUser) {
            fetchAttendance();
        }
    }, [currentUser]);

    if (loading) {
        return <Box display="flex" justifyContent="center" mt={4}><CircularProgress /></Box>;
    }

    if (attendanceData.length === 0) {
        return (
            <Box mt={4} textAlign="center">
                <Typography variant="h5" color="textSecondary">No records found</Typography>
                <Snackbar 
                    open={openSnackbar} 
                    autoHideDuration={6000} 
                    onClose={() => setOpenSnackbar(false)}
                    anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
                >
                    <Alert onClose={() => setOpenSnackbar(false)} severity="warning" sx={{ width: '100%' }}>
                        No records found
                    </Alert>
                </Snackbar>
            </Box>
        );
    }

    return (
        <Box sx={{ p: 4, fontFamily: 'Poppins, sans-serif' }}>
            <Typography variant="h4" gutterBottom fontWeight="bold" color="textPrimary">
                My Attendance
            </Typography>

            <TableContainer component={Paper} elevation={3} sx={{ borderRadius: 2 }}>
                <Table>
                    <TableHead sx={{ backgroundColor: '#f4f6f8' }}>
                        <TableRow>
                            <TableCell><strong>Course</strong></TableCell>
                            <TableCell align="center"><strong>Present</strong></TableCell>
                            <TableCell align="center"><strong>Absent</strong></TableCell>
                            <TableCell align="center"><strong>Percentage</strong></TableCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {attendanceData.map((row, index) => (
                            <TableRow key={index} hover>
                                <TableCell>{row.courseName}</TableCell>
                                <TableCell align="center">{row.present}</TableCell>
                                <TableCell align="center">{row.absent}</TableCell>
                                <TableCell align="center">
                                    <Typography color={row.percentage >= 75 ? 'success.main' : 'error.main'} fontWeight="bold">
                                        {row.percentage}%
                                    </Typography>
                                </TableCell>
                            </TableRow>
                        ))}
                    </TableBody>
                </Table>
            </TableContainer>
        </Box>
    );
};

export default ViewStdAttendance;