import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { 
    Box, Typography, Button, Paper, Table, TableBody, TableCell, 
    TableContainer, TableHead, TableRow, Select, MenuItem, 
    FormControl, InputLabel, Snackbar, Alert 
} from '@mui/material';
import axios from 'axios';

const FacultyAttendance = () => {
    const { currentUser } = useSelector(state => state.user);
    const token = localStorage.getItem('token') || localStorage.getItem('authToken');

    const [courses, setCourses] = useState([]);
    const [selectedCourse, setSelectedCourse] = useState('');
    const [students, setStudents] = useState([]);
    const [attendanceData, setAttendanceData] = useState([]);
    
    // For popup
    const [openSnackbar, setOpenSnackbar] = useState(false);
    const [snackbarMessage, setSnackbarMessage] = useState('');
    const [snackbarSeverity, setSnackbarSeverity] = useState('success');

    useEffect(() => {
        fetchCourses();
    }, []);

    const fetchCourses = async () => {
        try {
            const res = await axios.get(`${process.env.REACT_APP_BASE_URL || 'http://localhost:5000'}/api/attendance/faculty-courses`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setCourses(res.data);
        } catch (error) {
            console.error("Failed to fetch courses");
        }
    };

    const handleCourseChange = async (e) => {
        const courseId = e.target.value;
        setSelectedCourse(courseId);
        
        try {
            const res = await axios.get(`${process.env.REACT_APP_BASE_URL || 'http://localhost:5000'}/api/attendance/course-students/${courseId}`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setStudents(res.data);
            
            if (res.data.length === 0) {
                showSnackbar("No records found", "warning");
            }

            // Initialize attendance data
            const initialData = res.data.map(student => ({
                studentId: student._id || student.id,
                status: 'Present' // Default to present
            }));
            setAttendanceData(initialData);

        } catch (error) {
            showSnackbar("Failed to fetch students", "error");
        }
    };

    const handleToggleStatus = (studentId) => {
        setAttendanceData(prev => prev.map(record => {
            if (record.studentId === studentId) {
                return { ...record, status: record.status === 'Present' ? 'Absent' : 'Present' };
            }
            return record;
        }));
    };

    const handleSubmit = async () => {
        if (!selectedCourse) return showSnackbar("Please select a course first", "warning");
        if (attendanceData.length === 0) return showSnackbar("No students to mark", "warning");

        try {
            const res = await axios.post(`${process.env.REACT_APP_BASE_URL || 'http://localhost:5000'}/api/attendance`, {
                course: selectedCourse,
                records: attendanceData
            }, {
                headers: { Authorization: `Bearer ${token}` }
            });

            if (res.data.success) {
                showSnackbar("Attendance marked successfully", "success");
            }
        } catch (error) {
            if (error.response && error.response.data && error.response.data.message) {
                showSnackbar(error.response.data.message, "error");
            } else {
                showSnackbar("Attendance failed", "error");
            }
        }
    };

    const showSnackbar = (message, severity) => {
        setSnackbarMessage(message);
        setSnackbarSeverity(severity);
        setOpenSnackbar(true);
    };

    return (
        <Box sx={{ p: 4 }}>
            <Typography variant="h4" gutterBottom>
                Mark Attendance
            </Typography>

            <Paper sx={{ p: 3, mb: 4 }}>
                <FormControl fullWidth sx={{ mb: 3 }}>
                    <InputLabel id="course-select-label">Select Course</InputLabel>
                    <Select
                        labelId="course-select-label"
                        value={selectedCourse}
                        onChange={handleCourseChange}
                        label="Select Course"
                    >
                        {courses.map(course => (
                            <MenuItem key={course._id || course.id} value={course._id || course.id}>
                                {course.subName || course.name || course.courseName || `Course ${course._id}`}
                            </MenuItem>
                        ))}
                    </Select>
                </FormControl>

                {students.length > 0 && (
                    <TableContainer component={Paper} sx={{ mb: 3 }}>
                        <Table>
                            <TableHead>
                                <TableRow>
                                    <TableCell><strong>Student Name</strong></TableCell>
                                    <TableCell align="center"><strong>Status</strong></TableCell>
                                    <TableCell align="center"><strong>Toggle</strong></TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {students.map((student) => {
                                    const record = attendanceData.find(r => r.studentId === (student._id || student.id));
                                    const status = record ? record.status : 'Present';
                                    
                                    return (
                                        <TableRow key={student._id || student.id}>
                                            <TableCell>{student.name}</TableCell>
                                            <TableCell align="center">
                                                <Typography color={status === 'Present' ? 'green' : 'red'} fontWeight="bold">
                                                    {status}
                                                </Typography>
                                            </TableCell>
                                            <TableCell align="center">
                                                <Button 
                                                    variant="contained" 
                                                    color={status === 'Present' ? "error" : "success"}
                                                    onClick={() => handleToggleStatus(student._id || student.id)}
                                                    size="small"
                                                >
                                                    Mark {status === 'Present' ? 'Absent' : 'Present'}
                                                </Button>
                                            </TableCell>
                                        </TableRow>
                                    )
                                })}
                            </TableBody>
                        </Table>
                    </TableContainer>
                )}

                <Button 
                    variant="contained" 
                    color="primary" 
                    onClick={handleSubmit}
                    disabled={students.length === 0}
                    size="large"
                >
                    Submit Attendance
                </Button>
            </Paper>

            <Snackbar 
                open={openSnackbar} 
                autoHideDuration={6000} 
                onClose={() => setOpenSnackbar(false)}
                anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
            >
                <Alert onClose={() => setOpenSnackbar(false)} severity={snackbarSeverity} sx={{ width: '100%' }}>
                    {snackbarMessage}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default FacultyAttendance;
